Here is a Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    def sort(self, data: List[Any]) -> List[Any]:
        # Template method - skeleton of the algorithm
        arr = data[:]
        n = len(arr)
        # The concrete algorithm will define the loop structure
        self._sort_algorithm(arr, n)
        return arr

    @abstractmethod
    def _sort_algorithm(self, arr: List[Any], n: int) -> None:
        """Concrete subclasses implement the specific sorting steps"""
        pass

    @abstractmethod
    def compare(self, a: Any, b: Any) -> int:
        """Compare two elements. Return -1,0,1"""
        pass

    @abstractmethod
    def swap(self, arr: List[Any], i: int, j: int) -> None:
        """Swap two elements in the array"""
        pass


class BubbleSort(SortAlgorithm):
    def _sort_algorithm(self, arr: List[Any], n: int) -> None:
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(arr[j], arr[j + 1]) > 0:
                    self.swap(arr, j, j + 1)

    def compare(self, a: Any, b: Any) -> int:
        return (a > b) - (a < b)

    def swap(self, arr: List[Any], i: int, j: int) -> None:
        arr[i], arr[j] = arr[j], arr[i]


class SelectionSort(SortAlgorithm):
    def _sort_algorithm(self, arr: List[Any], n: int) -> None:
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(arr[j], arr[min_idx]) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(arr, i, min_idx)

    def compare(self, a: Any, b: Any) -> int:
        return (a > b) - (a < b)

    def swap(self, arr: List[Any], i: int, j: int) -> None:
        arr[i], arr[j] = arr[j], arr[i]


# Test
if __name__ == "__main__":
    ints = [5, 2, 9, 1, 5, 6]
    strings = ["banana", "apple", "cherry"]

    print("BubbleSort ints:", BubbleSort().sort(ints))
    print("SelectionSort ints:", SelectionSort().sort(ints))
    print("BubbleSort strings:", BubbleSort().sort(strings))
    print("SelectionSort strings:", SelectionSort().sort(strings))
```

The `SortAlgorithm.sort` template method defines the skeleton and delegates the algorithm-specific steps to `_sort_algorithm`, while `compare` and `swap` are the primitive operations used by all sorts.
